#!/usr/bin/env sh
# Creates .env for docker compose with fresh random secrets. Safe to run once; it never overwrites.
set -eu
cd "$(dirname "$0")/.."
if [ -f .env ]; then
  echo ".env already exists. Delete it first if you really want new secrets (everyone would be logged out)." >&2
  exit 1
fi
command -v openssl >/dev/null || { echo "openssl is needed to make secrets." >&2; exit 1; }
umask 077
cat > .env <<ENV
# Generated by scripts/init-env.sh. Keep this file private. See .env.example for every setting.
APP_URL=http://localhost:8030
WEB_PORT=8030
JWT_SECRET=$(openssl rand -base64 48 | tr -d '\n')
POSTGRES_PASSWORD=$(openssl rand -hex 24)
COOKIE_SECURE=true
SIGNUP_ENABLED=false
DEMO_MODE=false
# Emails go to the worker log until you set up SMTP:
MAIL_TRANSPORT=log
# MAIL_TRANSPORT=smtp
# MAIL_FROM="Your Lettings <lettings@example.com>"
# SMTP_HOST=smtp.example.com
# SMTP_PORT=587
# SMTP_USER=
# SMTP_PASS=
ENV
echo "Wrote .env with new secrets. Next: docker compose up -d, then open http://localhost:8030"
